import React, { useEffect, useState } from 'react';
import { getOrders } from '../services/api';

function OrdersPage({ user }) {
    const [orders, setOrders] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        async function fetchOrders() {
            try {
                if (!user) {
                    throw new Error('You need to be logged in to view orders.');
                }
                const ordersData = await getOrders(user.token);
                setOrders(ordersData);
                setLoading(false);
            } catch (err) {
                setError(err.message);
                setLoading(false);
            }
        }
        fetchOrders();
    }, [user]);

    if (loading) return <p>Loading orders...</p>;
    if (error) return <p className="text-red-500">{error}</p>;

    return (
        <div className="p-8">
            <h1 className="text-2xl font-bold mb-4">Your Orders</h1>
            {orders.length === 0 ? (
                <p>You have no orders yet.</p>
            ) : (
                <ul className="space-y-4">
                    {orders.map((order) => (
                        <li key={order._id} className="border p-4 rounded shadow">
                            <h2 className="text-xl font-bold">Order #{order._id}</h2>
                            <p>User ID: {order.user}</p>
                            <p>Status: {order.status}</p>
                            <p>Total Amount: ${order.totalAmount}</p>
                            <p>Order Date: {new Date(order.createdAt).toLocaleDateString()}</p>
                            <p>Last Updated: {new Date(order.updatedAt).toLocaleDateString()}</p>
                            <div className="mt-4">
                                <h3 className="text-lg font-bold">Products:</h3>
                                <ul className="list-disc pl-4">
                                    {order.products.map((product, index) => (
                                        <li key={index}>
                                            {product.name} - ${product.price} (x{product.quantity})
                                        </li>
                                    ))}
                                </ul>
                            </div>
                        </li>
                    ))}
                </ul>
            )}
        </div>
    );
}

export default OrdersPage;
